mapper.select:
SELECT COUNT(*)
FROM member_profile
WHERE mem_nickname = #{mem_nickname}

mapper.update:
UPDATE member_profile
SET 
	mem_img = #{mem_img, jdbcType=VARCHAR},
	 mem_intro = #{mem_intro, jdbcType=VARCHAR},
	  mem_nickname = #{mem_nickname, jdbcType=VARCHAR}

WHERE mem_idx = #{mem_idx}

UPDATE member_addr
SET
    mem_zipcode = #{mem_zipcode},
    mem_addr = #{mem_addr},
    mem_addr_detail = #{mem_addr_detail}
WHERE mem_idx = #{mem_idx}

UPDATE grade
SET
   grade_name = #{grade_name, jdbcType=VARCHAR},
   grade_discount_rate = #{grade_discount_rate, jdbcType=VARCHAR}

WHERE grade_idx = #{grade_idx}

UPDATE role
SET
    role_name = #{role_name, jdbcType=VARCHAR}

WHERE role_idx = #{role_idx}
